aspectRatio — Reduce a width by a height to its screen ratio, like 16:9.
  needs: width: number, height: number
  e.g. "what aspect ratio is 1920 by 1080" → {"width":1920,"height":1080}

fractionSimplify — Reduce a fraction like 6/8 to its lowest terms.
  needs: fraction: string
  e.g. "simplify 6/8" → {"fraction":"6/8"}

checkAnagram — Check whether two words or phrases use exactly the same letters.
  needs: first: string, second: string
  e.g. "are listen and silent anagrams" → {"first":"listen","second":"silent"}

complementaryColor — Find the colour opposite a given one on the colour wheel.
  needs: color: string
  e.g. "what is the complement of #2C6E8C" → {"color":"#2C6E8C"}

nearestNamedColor — Find the closest CSS colour name to a colour — what you would call it in words.
  needs: color: string
  e.g. "what colour name is closest to #556B2F" → {"color":"#556B2F"}

convertBase — Write a number in another base — 200 in base 7, 255 as hex, or 1011 back from binary. Any radix from 2 to 36.
  needs: value: string, fromBase: integer, toBase: integer
  e.g. "convert 255 to hexadecimal" → {"value":"255","fromBase":10,"toBase":16}

convertRomanNumeral — Convert a number to Roman numerals, or read Roman numerals back as a number.
  needs: value: string
  e.g. "what is 2026 in roman numerals" → {"value":"2026"}

convertCurrencyFixed — Convert an amount between currencies at an exchange rate you supply.
  needs: amount: number, from: string, to: string, rate: number
  e.g. "convert 100 EUR to USD at 1.0842" → {"amount":100,"from":"EUR","to":"USD","rate":1.0842}

currencyLookup — Look up what a currency code stands for — its name, symbol and how many decimal places it uses.
  needs: code: string
  e.g. "what is JPY" → {"code":"JPY"}

convertTime — Convert a length of time between units — how long 210 minutes runs to in hours.
  needs: amount: number, from: string, to: string
  e.g. "how many hours is 5400 seconds" → {"amount":5400,"from":"s","to":"h"}

